begin;
-- Instalación aditiva. No modifica precios, cursos ni órdenes históricas.
create table if not exists public.package_offers (
 id uuid primary key default gen_random_uuid(), code text not null unique,
 name text not null check(length(name) between 3 and 160),
 campus text not null check(campus in ('Centro','Norte','Virtual','Todas')),
 profile text not null check(profile in ('Nuevo','Activo sin paquete vigente','Retorno','Avanzado')),
 frequencies text[] not null check(cardinality(frequencies)>0 and frequencies <@ array['Intensivo','Semi-intensivo']),
 levels integer not null check(levels between 1 and 7), prep boolean not null default false,
 tuition integer not null check(tuition>0), materials integer not null check(materials>=0),
 base_tuition integer not null check(base_tuition>=tuition),
 conditions text not null check(length(conditions) between 10 and 4000),
 starts_at timestamptz not null, ends_at timestamptz not null, pay_until timestamptz not null,
 enabled boolean not null default false, version integer not null default 1,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check(ends_at>starts_at and pay_until>=ends_at),
 check(levels<5 or frequencies=array['Intensivo']::text[])
);
create table if not exists public.package_sales (
 order_id bigint primary key references public.orders(id),
 offer_id uuid not null references public.package_offers(id),
 token_hash text not null unique check(token_hash ~ '^[a-f0-9]{64}$'),
 snapshot jsonb not null, frequency text not null,
 pay_until timestamptz not null,
 eligibility text not null default 'pending' check(eligibility in ('pending','approved','rejected')),
 eligibility_note text, validated_by uuid references auth.users(id), validated_at timestamptz,
 entitlement_status text not null default 'unpaid' check(entitlement_status in ('unpaid','active','review','frozen')),
 checkout_url text, mp_order_id text unique, payment_detail jsonb,
 created_at timestamptz not null default now()
);
create table if not exists public.package_credits (
 id uuid primary key default gen_random_uuid(), order_id bigint not null references public.package_sales(order_id),
 ordinal integer not null check(ordinal between 1 and 8), kind text not null check(kind in ('nivel','preparacion')),
 status text not null default 'available' check(status in ('available','processing','assigned','completed','review')),
 course_id bigint references public.courses(id), mapping jsonb, academic_level text,
 prerequisite_note text, assigned_by uuid references auth.users(id), assigned_at timestamptz,
 completed_by uuid references auth.users(id), completed_at timestamptz, q10_response jsonb,
 unique(order_id,ordinal)
);
create index if not exists package_credits_order_idx on public.package_credits(order_id);
alter table public.package_offers enable row level security;
alter table public.package_sales enable row level security;
alter table public.package_credits enable row level security;
revoke all on public.package_offers,public.package_sales,public.package_credits from public,anon,authenticated;
grant select on public.package_offers,public.package_sales,public.package_credits to authenticated;
grant all on public.package_offers,public.package_sales,public.package_credits to service_role;
drop policy if exists packages_staff_offers on public.package_offers;
create policy packages_staff_offers on public.package_offers for select to authenticated using (
 exists(select 1 from public.admin_profiles a where a.user_id=(select auth.uid()) and (a.can_courses or a.is_superadmin or a.can_accounting)));
drop policy if exists packages_staff_sales on public.package_sales;
create policy packages_staff_sales on public.package_sales for select to authenticated using (
 exists(select 1 from public.admin_profiles a where a.user_id=(select auth.uid()) and (a.can_courses or a.is_superadmin or a.can_accounting)));
drop policy if exists packages_staff_credits on public.package_credits;
create policy packages_staff_credits on public.package_credits for select to authenticated using (
 exists(select 1 from public.admin_profiles a where a.user_id=(select auth.uid()) and (a.can_courses or a.is_superadmin or a.can_accounting)));

create or replace function public.reserve_package(p_offer uuid,p_frequency text,p_student jsonb,p_hash text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare f public.package_offers; o public.orders; s public.package_sales; n text;
begin
 -- Reintentos de la misma reserva devuelven el mismo pedido sin duplicar ingresos.
 perform pg_advisory_xact_lock(hashtextextended(p_hash,0));
 select * into s from public.package_sales where token_hash=p_hash;
 if found then
  select * into o from public.orders where id=s.order_id;
  return jsonb_build_object('orderNumber',o.order_number,'amount',o.amount);
 end if;
 select * into f from public.package_offers where id=p_offer for share;
 if not found or not f.enabled or now()<f.starts_at or now()>=f.ends_at then raise exception 'La promoción no está disponible'; end if;
 if not(p_frequency=any(f.frequencies)) then raise exception 'Intensidad no permitida'; end if;
 if coalesce(p_student->>'accepted_privacy','')<>'true' or coalesce(p_student->>'accepted_terms','')<>'true' then raise exception 'Acepta las condiciones y el tratamiento de datos'; end if;
 n := 'IBR-P-'||gen_random_uuid()::text;
 insert into public.orders(order_number,product_type,course_name,modality,campus,first_name,last_name,email,phone,document_type,document_number,birth_date,gender,address,city_name,amount,currency,quantity,unit_price,unit_amount,payment_status,order_status,q10_status,hubspot_status,accepted_terms,accepted_privacy,source)
 values(n,'package',f.name,case when f.campus='Virtual' then 'Virtual' else 'Presencial' end,f.campus,p_student->>'first_name',p_student->>'last_name',p_student->>'email',p_student->>'phone',p_student->>'document_type',p_student->>'document_number',nullif(p_student->>'birth_date','')::date,p_student->>'gender',p_student->>'address',p_student->>'city_name',f.tuition+f.materials,'COP',1,f.tuition+f.materials,f.tuition+f.materials,'pending','pending','awaiting_course','pending',true,true,'ibraco-promociones') returning * into o;
 insert into public.package_sales(order_id,offer_id,token_hash,snapshot,frequency,pay_until)
 values(o.id,f.id,p_hash,to_jsonb(f)-'created_at'-'updated_at',p_frequency,f.pay_until);
 return jsonb_build_object('orderNumber',n,'amount',o.amount);
end $$;
revoke all on function public.reserve_package(uuid,text,jsonb,text) from public,anon,authenticated;
grant execute on function public.reserve_package(uuid,text,jsonb,text) to service_role;

create or replace function public.activate_package(p_order bigint,p_review boolean default false)
returns text language plpgsql security invoker set search_path='' as $$
declare s public.package_sales; o public.orders; i integer;
begin
 select * into s from public.package_sales where order_id=p_order for update;
 if not found then raise exception 'Paquete inexistente'; end if;
 select * into o from public.orders where id=p_order;
 if o.payment_status<>'paid' then raise exception 'Falta pago confirmado'; end if;
 if p_review or s.eligibility<>'approved' then
  update public.package_sales set entitlement_status='review' where order_id=p_order;
  return 'review';
 end if;
 for i in 1..(s.snapshot->>'levels')::integer loop
  insert into public.package_credits(order_id,ordinal,kind) values(p_order,i,'nivel') on conflict(order_id,ordinal) do nothing;
 end loop;
 if (s.snapshot->>'prep')::boolean then
  insert into public.package_credits(order_id,ordinal,kind) values(p_order,(s.snapshot->>'levels')::integer+1,'preparacion') on conflict(order_id,ordinal) do nothing;
 end if;
 update public.package_sales set entitlement_status='active' where order_id=p_order;
 return 'active';
end $$;
revoke all on function public.activate_package(bigint,boolean) from public,anon,authenticated;
grant execute on function public.activate_package(bigint,boolean) to service_role;

create or replace function public.claim_package_credit(p_credit uuid,p_course bigint,p_actor uuid,p_level text,p_note text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare c public.package_credits; s public.package_sales; f public.courses;
begin
 select * into c from public.package_credits where id=p_credit;
 if not found then raise exception 'Crédito inexistente'; end if;
 select * into s from public.package_sales where order_id=c.order_id for update;
 -- El bloqueo de la venta serializa asignaciones de todos sus créditos.
 select * into c from public.package_credits where id=p_credit for update;
 if s.entitlement_status<>'active' or c.status<>'available' then raise exception 'Crédito no disponible'; end if;
 if not exists(select 1 from public.orders where id=c.order_id and payment_status='paid') then raise exception 'Pago no vigente'; end if;
 if exists(select 1 from public.package_credits where order_id=c.order_id and ordinal<c.ordinal and status<>'completed') then raise exception 'Primero completa y valida el nivel anterior'; end if;
 if length(trim(p_note))<10 or length(trim(p_level))<1 then raise exception 'Indica nivel académico y evidencia del prerrequisito'; end if;
 select * into f from public.courses where id=p_course;
 if not found or f.status<>'published' or coalesce(f.q10_program_code,'')='' or f.q10_period_id is null or f.q10_site_journey_id is null then raise exception 'El curso requiere publicación y mapeo Q10'; end if;
 if s.snapshot->>'campus'<>'Todas' and lower(coalesce(f.campus,'')) not like '%'||lower(s.snapshot->>'campus')||'%' and not (s.snapshot->>'campus'='Virtual' and lower(coalesce(f.modality,'')) like '%virtual%') then raise exception 'La sede/modalidad no corresponde al paquete'; end if;
 if s.snapshot->>'campus' in ('Centro','Norte') and lower(coalesce(f.modality,'')) like '%virtual%' then raise exception 'El paquete es presencial'; end if;
 if c.kind='nivel' and lower(coalesce(f.level,''))<>lower(s.frequency) then raise exception 'La intensidad del curso no coincide'; end if;
 update public.package_credits set status='processing',course_id=p_course,academic_level=p_level,prerequisite_note=p_note,assigned_by=p_actor,assigned_at=now(),mapping=jsonb_build_object('program',f.q10_program_code,'period',f.q10_period_id,'site',f.q10_site_journey_id) where id=c.id returning * into c;
 return to_jsonb(c);
end $$;
revoke all on function public.claim_package_credit(uuid,bigint,uuid,text,text) from public,anon,authenticated;
grant execute on function public.claim_package_credit(uuid,bigint,uuid,text,text) to service_role;

